agent_base_units.command:
node -e "
const acorn = require('acorn');
const opts = {ecmaVersion: 'latest', sourceType: 'module'};
const cases = [
  'using x = 1;',
  'await using x = 1;',
  '{ using x = 1; }',
  'function f(){ using x = 1; }',
  'for (using x of y) {}',
  'for await (using x of y) {}',
  'for (await using x of y) {}',
  'for await (await using x of y) {}',
  'for (using x in y) {}',
  'using {a} = x;',
  'using [a] = x;',
  'using x;',
  'using\nx = 1;',
  'await using x;',
];
for (const code of cases) {
  try {
    const ast = acorn.parse(code, opts);
    const b = ast.body[0];
    let out;
    if (b.type==='VariableDeclaration' || b.type==='ForOfStatement' || b.type==='ForInStatement') {
      out = {type:b.type, kind:b.kind||null, start:b.start, end:b.end};
      if (b.type==='ForOfStatement') out.left=b.left && b.left.kind;
      if (b.type==='ForInStatement') out.left=b.left && b.left.kind;
    } else out = b.type;
    console.log(JSON.stringify(code), '=>', JSON.stringify(out));
  } catch(e) { console.log(JSON.stringify(code), 'ERR:', e.message); }
}
"

